-- DRAFT FOR REVIEW. NOT APPLIED. Generated by scripts/tenancy/generate_migrations.py -- do not edit by hand.
-- Backlog 1.19, decision D-37: existing data belongs to tenant label 'default'; row-level security is the
-- second wall; BP staff get read-only, logged support access.
-- Part 6: stamp the tenant on every new row
-- APPLY AFTER part 1 and AFTER the application that sets app.tenant_id is running (tenant_context);
-- order: 1 -> 6 -> 2 -> [app] -> 3 -> 5 -> 4.
-- A BEFORE INSERT trigger fills tenant_id from the connection's app.tenant_id when the insert did not
-- name one, so ~200 INSERT statements in the code do not each have to. Rules:
--   * an insert that names a tenant keeps it (a platform job may name one; row-level security, part 4,
--     still refuses a name that is not the caller's);
--   * an insert that names none and has no tenant on the connection stays NULL: part 2 relabels it
--     until part 3, and part 3's NOT NULL refuses it after -- it is never guessed into 'default'.
-- Every owned table has DEFAULT 'default' at this point (part 1 added it; 12 tables already had
-- it). A default fills the label BEFORE this trigger runs, so each table's default is dropped in the same
-- transaction that creates its trigger (no moment with neither). Existing rows keep their label.
-- Reversible: 6_stamp_on_insert_rollback.sql (puts the default back).

CREATE OR REPLACE FUNCTION proc.bp_stamp_tenant() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.tenant_id IS NULL THEN
    NEW.tenant_id := nullif(current_setting('app.tenant_id', true), '');
  END IF;
  RETURN NEW;
END $$;

BEGIN;
SET LOCAL lock_timeout = '3s';
DROP TRIGGER IF EXISTS tr_bp_stamp_tenant ON proc.agent_plan;
CREATE TRIGGER tr_bp_stamp_tenant BEFORE INSERT ON proc.agent_plan
  FOR EACH ROW EXECUTE FUNCTION proc.bp_stamp_tenant();
ALTER TABLE proc.agent_plan ALTER COLUMN tenant_id DROP DEFAULT;
COMMIT;

